arguments.content:
/* ChartPulse Design System */
:root {
  /* Colors - Dark Theme */
  --bg-primary: oklch(12% 0.02 265);
  --bg-secondary: oklch(14% 0.02 265);
  --bg-tertiary: oklch(16% 0.02 265);
  --bg-card: oklch(15% 0.02 265);

  /* Brand Colors */
  --accent-blue: oklch(55% 0.22 265);
  --accent-blue-dim: oklch(50% 0.18 265);

  /* Semantic Colors */
  --gain: oklch(65% 0.18 145);
  --loss: oklch(60% 0.22 25);
  --neutral: oklch(55% 0.03 265);

  /* Text */
  --text-primary: oklch(95% 0.01 265);
  --text-secondary: oklch(70% 0.02 265);
  --text-muted: oklch(45% 0.02 265);

  /* Borders */
  --border: oklch(25% 0.02 265);
  --border-accent: oklch(35% 0.02 265);

  /* Tier badges */
  --tier-platinum: oklch(70% 0.08 260);
  --tier-gold: oklch(75% 0.15 50);

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;

  /* Border radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

/* Navigation */
.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--space-lg);
  height: 56px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
}

.nav-brand svg {
  width: 28px;
  height: 28px;
}

.nav-links {
  display: flex;
  gap: var(--space-lg);
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  padding: var(--space-sm) 0;
  transition: color var(--transition-fast);
}

.nav-links a:hover {
  color: var(--text-primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--accent-blue);
  color: white;
}

.btn-primary:hover {
  background: var(--accent-blue-dim);
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  background: var(--border);
}

.btn-sm {
  padding: var(--space-xs) var(--space-sm);
  font-size: 12px;
}

/* Tabs */
.tabs {
  display: flex;
  gap: var(--space-xs);
  background: var(--bg-tertiary);
  padding: 3px;
  border-radius: var(--radius-md);
}

.tab {
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  transition: all var(--transition-fast);
}

.tab:hover {
  color: var(--text-primary);
}

.tab.active {
  background: var(--accent-blue);
  color: white;
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-md);
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

/* Market Data Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  padding: var(--space-sm) var(--space-md);
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border);
}

.data-table td {
  padding: var(--space-sm) var(--space-md);
  font-size: 13px;
  border-bottom: 1px solid var(--border);
}

.data-table tr:hover {
  background: var(--bg-tertiary);
}

.data-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* Price Change Indicators */
.change {
  display: inline-flex;
  align-items: center;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
}

.change.positive {
  background: oklch(25% 0.15 145);
  color: var(--gain);
}

.change.negative {
  background: oklch(25% 0.15 25);
  color: var(--loss);
}

.change.neutral {
  background: var(--bg-tertiary);
  color: var(--text-muted);
}

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.badge-platinum {
  background: linear-gradient(135deg, oklch(60% 0.1 260), oklch(70% 0.08 260));
  color: white;
}

.badge-gold {
  background: linear-gradient(135deg, oklch(65% 0.15 50), oklch(75% 0.12 45));
  color: oklch(20% 0.05 50);
}

.rating-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 600;
}

.rating-badge.excellent {
  color: var(--gain);
}

.rating-badge.great {
  color: var(--accent-blue);
}

.rating-badge.good {
  color: var(--neutral);
}

/* Tier Stars */
.tier-star {
  color: var(--tier-platinum);
}

/* Sparkline */
.sparkline {
  display: inline-block;
  width: 60px;
  height: 20px;
}

.sparkline svg {
  width: 100%;
  height: 100%;
}

/* Section Styles */
.section {
  padding: var(--space-xl) 0;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

/* Hero Section */
.hero {
  padding: var(--space-2xl) 0;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}

.hero h1 {
  font-size: 48px;
  font-weight: 700;
  margin-bottom: var(--space-md);
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-blue) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 18px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto var(--space-lg);
}

.hero-actions {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
}

/* Market Summary Bar */
.market-summary {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: var(--space-md) 0;
  overflow-x: auto;
}

.market-summary::-webkit-scrollbar {
  height: 4px;
}

.market-summary::-webkit-scrollbar-track {
  background: var(--bg-tertiary);
}

.market-summary::-webkit-scrollbar-thumb {
  background: var(--border-accent);
  border-radius: 2px;
}

.market-items {
  display: flex;
  gap: var(--space-xl);
  padding: 0 var(--space-lg);
}

.market-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: max-content;
}

.market-item .ticker {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.market-item .price {
  font-size: 14px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.market-item .change {
  font-size: 11px;
}

/* Grid Layouts */
.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-md);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-md);
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
}

/* Watchlist Accordion */
.watchlist-category {
  border-bottom: 1px solid var(--border);
}

.watchlist-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.watchlist-header:hover {
  background: var(--bg-tertiary);
}

.watchlist-header h4 {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.watchlist-header .chevron {
  transition: transform var(--transition-fast);
}

.watchlist-category.open .chevron {
  transform: rotate(180deg);
}

.watchlist-items {
  display: none;
  padding: var(--space-xs) 0;
}

.watchlist-category.open .watchlist-items {
  display: block;
}

.watchlist-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-xs) var(--space-md);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.watchlist-item:hover {
  background: var(--bg-tertiary);
}

.watchlist-item.active {
  background: oklch(30% 0.15 265);
  border-left: 2px solid var(--accent-blue);
}

.watchlist-item .symbol {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.watchlist-item .price {
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.watchlist-item .change {
  font-size: 11px;
}

/* Candlestick Chart Placeholder */
.chart-area {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.chart-area::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, var(--border) 1px, transparent 1px),
    linear-gradient(var(--border) 1px, transparent 1px);
  background-size: 40px 40px;
  opacity: 0.3;
}

.chart-content {
  position: relative;
  z-index: 1;
  text-align: center;
}

.chart-content p {
  color: var(--text-muted);
  font-size: 14px;
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: var(--space-2xl) 0 var(--space-lg);
  margin-top: var(--space-2xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
  margin-bottom: var(--space-xl);
}

.footer-col h5 {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: var(--space-md);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: var(--space-sm);
}

.footer-col a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 13px;
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-lg);
  border-top: 1px solid var(--border);
}

.footer-bottom p {
  font-size: 12px;
  color: var(--text-muted);
}

.stats-banner {
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  text-align: center;
  margin-bottom: var(--space-xl);
}

.stats-banner h3 {
  font-size: 28px;
  font-weight: 700;
  color: var(--accent-blue);
  margin-bottom: var(--space-xs);
}

.stats-banner p {
  color: var(--text-secondary);
  font-size: 14px;
}

/* Broker Cards */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  transition: all var(--transition-fast);
}

.broker-card:hover {
  border-color: var(--border-accent);
  transform: translateY(-2px);
}

.broker-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-md);
}

.broker-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}

.broker-meta {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  margin-bottom: var(--space-md);
  font-size: 13px;
  color: var(--text-secondary);
}

.broker-stats {
  display: flex;
  gap: var(--space-lg);
  padding-top: var(--space-md);
  border-top: 1px solid var(--border);
}

.broker-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.broker-stat .label {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.broker-stat .value {
  font-size: 14px;
  font-weight: 600;
}

.broker-promotion {
  margin-top: var(--space-md);
  padding: var(--space-sm);
  background: oklch(30% 0.12 265);
  border-radius: var(--radius-sm);
  font-size: 12px;
  color: var(--accent-blue);
  text-align: center;
}

/* Idea Cards */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  margin-bottom: var(--space-md);
}

.idea-header {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-bottom: var(--space-md);
}

.idea-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
}

.idea-meta {
  flex: 1;
}

.idea-author {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.idea-time {
  font-size: 12px;
  color: var(--text-muted);
}

.idea-content {
  margin-bottom: var(--space-md);
}

.idea-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.idea-description {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.6;
}

.idea-footer {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.idea-stat {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--text-muted);
}

.idea-chart-preview {
  height: 80px;
  background: var(--bg-tertiary);
  border-radius: var(--radius-md);
  margin: var(--space-md) 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

/* Timeframe Toggle */
.timeframe-toggle {
  display: flex;
  gap: 2px;
  background: var(--bg-tertiary);
  padding: 3px;
  border-radius: var(--radius-md);
}

.timeframe-btn {
  padding: var(--space-xs) var(--space-sm);
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.timeframe-btn:hover {
  color: var(--text-primary);
}

.timeframe-btn.active {
  background: var(--accent-blue);
  color: white;
}

/* Stock Detail Panel */
.detail-panel {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.detail-header {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
}

.detail-ticker {
  font-size: 20px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.detail-ticker .exchange {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 400;
}

.detail-price {
  font-size: 32px;
  font-weight: 700;
  margin: var(--space-sm) 0;
  font-variant-numeric: tabular-nums;
}

.detail-change {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  font-size: 14px;
}

.detail-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-sm);
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
}

.stat-item {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
}

.stat-item .label {
  color: var(--text-muted);
}

.stat-item .value {
  font-weight: 600;
}

/* Financials Table */
.financials-tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
}

.financials-tab {
  flex: 1;
  padding: var(--space-md);
  text-align: center;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}

.financials-tab:hover {
  color: var(--text-primary);
}

.financials-tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-xl);
}

.pagination button {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  background: var(--bg-card);
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  cursor: pointer;
  font-size: 14px;
  transition: all var(--transition-fast);
}

.pagination button:hover:not(:disabled) {
  border-color: var(--accent-blue);
  color: var(--accent-blue);
}

.pagination button.active {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
  color: white;
}

.pagination button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Section Title */
.section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.section-title h2 {
  font-size: 18px;
  font-weight: 700;
}

/* Filter Pills */
.filter-pills {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
}

.filter-pill {
  padding: var(--space-xs) var(--space-md);
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 500;
  border-radius: 20px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.filter-pill:hover {
  border-color: var(--accent-blue);
  color: var(--accent-blue);
}

.filter-pill.active {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
  color: white;
}

/* Responsive */
@media (max-width: 1200px) {
  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .grid-4, .grid-3, .grid-2 {
    grid-template-columns: 1fr;
  }

  .hero h1 {
    font-size: 32px;
  }

  .market-items {
    gap: var(--space-lg);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Hide content for tab switches */
.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* Chart Page Specific */
.chart-layout {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: var(--space-md);
  height: calc(100vh - 56px);
}

.chart-main {
  display: flex;
  flex-direction: column;
  padding: var(--space-md);
}

.chart-sidebar {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md);
  border-bottom: 1px solid var(--border);
  background: var(--bg-card);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}

.chart-toolbar-left {
