  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-bottom: var(--space-md);
}

.idea-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
}

.idea-meta {
  flex: 1;
}

.idea-author {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.idea-time {
  font-size: 12px;
  color: var(--text-muted);
}

.idea-content {
  margin-bottom: var(--space-md);
}

.idea-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.idea-description {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.6;
}

.idea-footer {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.idea-stat {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--text-muted);
}

.idea-chart-preview {
  height: 80px;
  background: var(--bg-tertiary);
  border-radius: var(--radius-md);
  margin: var(--space-md) 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

/* Timeframe Toggle */
.timeframe-toggle {
  display: flex;
  gap: 2px;
  background: var(--bg-tertiary);
  padding: 3px;
  border-radius: var(--radius-md);
}

.timeframe-btn {
  padding: var(--space-xs) var(--space-sm);
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.timeframe-btn:hover {
  color: var(--text-primary);
}

.timeframe-btn.active {
  background: var(--accent-blue);
  color: white;
}

/* Stock Detail Panel */
.detail-panel {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.detail-header {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
}

.detail-ticker {
  font-size: 20px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.detail-ticker .exchange {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 400;
}

.detail-price {
  font-size: 32px;
  font-weight: 700;
  margin: var(--space-sm) 0;
  font-variant-numeric: tabular-nums;
}

.detail-change {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  font-size: 14px;
}

.detail-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-sm);
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
}

.stat-item {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
}

.stat-item .label {
  color: var(--text-muted);
}

.stat-item .value {
  font-weight: 600;
}

/* Financials Table */
.financials-tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
}

.financials-tab {
  flex: 1;
  padding: var(--space-md);
  text-align: center;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}

.financials-tab:hover {
  color: var(--text-primary);
}

.financials-tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-xl);
}

.pagination button {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  background: var(--bg-card);
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  cursor: pointer;
  font-size: 14px;
  transition: all var(--transition-fast);
}

.pagination button:hover:not(:disabled) {
  border-color: var(--accent-blue);
  color: var(--accent-blue);
}

.pagination button.active {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
  color: white;
}

.pagination button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Section Title */
.section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.section-title h2 {
  font-size: 18px;
  font-weight: 700;
}

/* Filter Pills */
.filter-pills {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
}

.filter-pill {
  padding: var(--space-xs) var(--space-md);
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 500;
  border-radius: 20px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.filter-pill:hover {
  border-color: var(--accent-blue);
  color: var(--accent-blue);
}

.filter-pill.active {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
  color: white;
}

/* Responsive */
@media (max-width: 1200px) {
  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .grid-4, .grid-3, .grid-2 {
    grid-template-columns: 1fr;
  }

  .hero h1 {
    font-size: 32px;
  }

  .market-items {
    gap: var(--space-lg);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Hide content for tab switches */
.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* Chart Page Specific */
.chart-layout {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: var(--space-md);
  height: calc(100vh - 56px);
}

.chart-main {
  display: flex;
  flex-direction: column;
  padding: var(--space-md);
}

.chart-sidebar {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md);
  border-bottom: 1px solid var(--border);
  background: var(--bg-card);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}

.chart-toolbar-left {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.chart-toolbar-right {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.chart-container {
  flex: 1;
  background: var(--bg-card);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  min-height: 400px;
  position: relative;
  overflow: hidden;
}

.chart-candles {
  position: absolute;
  inset: 20px;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  padding: 0 10px;
}

.candle {
  width: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.candle-body {
  width: 100%;
  border-radius: 2px;
}

.candle-bullish {
  background: var(--gain);
}

.candle-bearish {
  background: var(--loss);
}

.candle-wick {
  width: 1px;
}

.candle-bullish .candle-wick {
  background: var(--gain);
}

.candle-bearish .candle-wick {
  background: var(--loss);
}

/* Sidebar Sections */
.sidebar-section {
  border-bottom: 1px solid var(--border);
}

.sidebar-section:last-child {
  border-bottom: none;
}

.sidebar-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md);
  cursor: pointer;
}

.sidebar-section-header h3 {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* Stock List in Sidebar */
.stock-list-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.stock-list-item:hover {
  background: var(--bg-tertiary);
}

.stock-list-item.active {
  background: oklch(25% 0.15 265);
  border-left: 2px solid var(--accent-blue);
}

.stock-list-item .left {
  display: flex;
  flex-direction: column;
}

.stock-list-item .symbol {
  font-size: 13px;
  font-weight: 600;
}

.stock-list-item .name {
  font-size: 11px;
  color: var(--text-muted);
}

.stock-list-item .right {
  text-align: right;
}

.stock-list-item .price {
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.stock-list-item .change {
  font-size: 11px;
}

/* Scrollbar Styles */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: var(--bg-tertiary);
}

::-webkit-scrollbar-thumb {
  background: var(--border-accent);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* Ideas Page Specific */
.ideas-header {
  background: var(--bg-secondary);
  padding: var(--space-xl) 0;
  border-bottom: 1px solid var(--border);
}

.ideas-hero {
  text-align: center;
  margin-bottom: var(--space-xl);
}

.ideas-hero h1 {
  font-size: 32px;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.ideas-hero p {
  color: var(--text-secondary);
}

.ideas-filters {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.ideas-feed {
  max-width: 800px;
  margin: 0 auto;
  padding: var(--space-xl) var(--space-lg);
}

/* Markets Page */
.markets-tabs {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  padding: var(--space-md) 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: var(--space-xl);
}

.markets-tab {
  padding: var(--space-sm) var(--space-lg);
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}

.markets-tab:hover {
  color: var(--text-primary);
}

.markets-tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

/* Brokers Page */
.brokers-hero {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-tertiary) 100%);
  padding: var(--space-2xl) 0;
  text-align: center;
  margin-bottom: var(--space-xl);
}

.brokers-hero h1 {
  font-size: 36px;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.brokers-hero p {
  color: var(--text-secondary);
  max-width: 500px;
  margin: 0 auto;
}

.broker-filters {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);
  flex-wrap: wrap;
}

.broker-listings {
  display: grid;
  gap: var(--space-md);
}

.broker-card-large {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: var(--space-lg);
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
}

.broker-info {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.broker-top {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.broker-logo {
  width: 48px;
  height: 48px;
  background: var(--bg-tertiary);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 16px;
}

.broker-details h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 2px;
}

.broker-rating-large {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 13px;
}

.broker-actions-col {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  gap: var(--space-md);
}

/* Mini Chart */
.mini-chart {
  height: 40px;
  width: 80px;
  display: flex;
  align-items: flex-end;
  gap: 2px;
}

.mini-chart-bar {
  flex: 1;
  border-radius: 1px;
  min-width: 3px;
}

/* Tab Content Areas */
.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
}

/* Table container */
.table-container {
  overflow-x: auto;
}

.table-container .data-table tr:last-child {
